/**
 * PR comment posting. The markdown itself lives in comment-markdown.ts, which
 * has no `@actions/*` imports and is therefore unit tested (PRE-2665).
 */


async function postOrUpdateComment(result, config) {
    const { /* context */ "_": context } = github_namespaceObject;
    const prNumber = context.payload.pull_request?.number;
    if (!prNumber)
        return;
    const octokit = getOctokit(config.githubToken);
    const body = generateMarkdown(result);
    // Search for existing comment
    const { data: comments } = await octokit.rest.issues.listComments({
        owner: context.repo.owner,
        repo: context.repo.repo,
        issue_number: prNumber,
        per_page: 100,
    });
    const existing = comments.find(c => c.body?.includes(COMMENT_MARKER));
    if (existing) {
        await octokit.rest.issues.updateComment({
            owner: context.repo.owner,
            repo: context.repo.repo,
            comment_id: existing.id,
            body,
        });
    }
    else {
        await octokit.rest.issues.createComment({
            owner: context.repo.owner,
            repo: context.repo.repo,
            issue_number: prNumber,
            body,
        });
    }
}

