function getCheckpointsByCategory(category) {
  return TYPOGRAPHY_CHECKPOINTS.filter((cp) => cp.category === category);
}
function getCheckpointById(id) {
  return TYPOGRAPHY_CHECKPOINTS.find((cp) => cp.id === id);
}
function checkpointWeight(id) {
  return getCheckpointById(id)?.weight ?? 0.5;
}
function getCheckpointsByRiskLevel(riskLevel) {
  return TYPOGRAPHY_CHECKPOINTS.filter((cp) => cp.riskLevel === riskLevel);
}
function scoreToGrade2(score) {
  if (score >= 90) return "A";
  if (score >= 80) return "B";
  if (score >= 70) return "C";
  if (score >= 60) return "D";
  return "F";
}
