  server.tool(
    "validate_tailwind_config",
    `Validates a Tailwind CSS configuration for design system compliance.

Catches design system violations at the source - the config file itself.
Detects non-standard colors, missing semantic tokens, and conflicting values.

Parameters:
- config (required): The tailwind.config.js content as a string

Returns:
- valid: boolean - whether the config passes validation
- score: 0-100 compliance score
- issues: Array of problems found with:
  - type: 'error' | 'warning'
  - category: What kind of issue
  - message: Description of the problem
  - location: Where in the config
  - fix: How to fix it
- recommendations: Suggestions for improvement
- summary: Quick overview of config health

Use this to validate Tailwind configs before they cause design system drift.`,
    {
      config: import_zod35.z.string().describe("The tailwind.config.js content")
    },
    async ({ config }) => {
      debug2("validate_tailwind_config called", { configLength: config.length });
      const issues = [];
      const recommendations = [];
      const hexColorPattern2 = /#[0-9a-fA-F]{3,8}/g;
      const hexMatches = config.match(hexColorPattern2) || [];
      if (hexMatches.length > 0) {
        issues.push({
          type: "warning",
          category: "colors",
          message: `Found ${hexMatches.length} hardcoded hex color(s)`,
          location: "theme.extend.colors",
          fix: 'Use CSS variables: "var(--color-name)" instead of hex values'
        });
      }
      const tailwindColorPatterns = [
        { pattern: /colors\.(zinc|gray|slate|neutral)/gi, name: "gray palette" },
        { pattern: /colors\.(red|green|blue|yellow|orange|purple|pink)/gi, name: "default colors" }
      ];
      for (const { pattern, name } of tailwindColorPatterns) {
        if (pattern.test(config)) {
          issues.push({
            type: "error",
            category: "colors",
            message: `Using Tailwind default ${name} instead of semantic tokens`,
            location: "theme.extend.colors",
            fix: "Replace with semantic color tokens (surface, text, status, brand)"
          });
        }
      }
      const semanticCategories = ["surface", "text", "border", "status"];
      for (const category of semanticCategories) {
        if (!config.includes(category)) {
          issues.push({
            type: "warning",
            category: "structure",
            message: `Missing "${category}" semantic token category`,
            fix: `Add ${category} tokens to theme.extend.colors`
          });
        }
      }
      if (/\[['"]?\d+px['"]?\]/g.test(config)) {
        issues.push({
          type: "warning",
          category: "spacing",
          message: "Arbitrary pixel values found in config",
          fix: "Use spacing scale values instead of arbitrary pixels"
        });
      }
      const cssVarPattern2 = /var\(--[\w-]+\)/g;
      const cssVarMatches = config.match(cssVarPattern2) || [];
      if (cssVarMatches.length > 0) {
        recommendations.push(`Good: Using ${cssVarMatches.length} CSS variables for theming`);
      } else if (hexMatches.length > 0) {
        recommendations.push("Consider using CSS variables for theme support");
      }
      if (!config.includes("darkMode")) {
        issues.push({
          type: "warning",
          category: "theming",
          message: "No darkMode configuration found",
          fix: 'Add darkMode: "class" or darkMode: "media" to support dark mode'
        });
      }
      const errorCount = issues.filter((i) => i.type === "error").length;
      const warningCount = issues.filter((i) => i.type === "warning").length;
      let score = 100;
      score -= errorCount * 20;
      score -= warningCount * 5;
      score = Math.max(0, Math.min(100, score));
      const result = {
        valid: errorCount === 0,
        score,
        issues,
        recommendations: recommendations.length > 0 ? recommendations : issues.length === 0 ? ["Config follows design system standards"] : ["Address issues above to improve config health"],
        summary: score >= 90 ? "Excellent! Config follows design system standards." : score >= 70 ? "Good config with minor issues to address." : score >= 50 ? "Several issues found. Review and fix errors first." : "Significant problems detected. Config needs attention."
      };
      return {
        content: [
          {
            type: "text",
            text: JSON.stringify(result, null, 2)
          }
        ]
      };
    }
  );
