  server.tool(
    "suggest_animation",
    `Suggest animation primitives for a given intent or context.

Takes a natural language description of what should be animated and suggests
the most appropriate primitive(s) from the design system.

Parameters:
- intent (required): What should be animated (e.g., "hero entrance", "loading state", "content reveal")
- design_system_id (optional): Scope to a specific design system
- personality (optional): Motion personality slug to apply
- count (optional): Number of suggestions (default 3)

Returns:
- suggestions: Array of { primitive, confidence, rationale, timing, alternatives }
- personality_applied: Whether personality token overrides were applied`,
    {
      intent: import_zod38.z.string().describe('What should be animated (e.g., "hero entrance", "loading state")'),
      design_system_id: import_zod38.z.string().uuid().optional().describe("Scope to a specific design system"),
      personality: import_zod38.z.string().optional().describe("Motion personality slug to apply"),
      count: import_zod38.z.number().optional().default(3).describe("Number of suggestions to return"),
      layerId: import_zod38.z.string().uuid().optional().describe("Layer UUID for layer-specific primitive and personality resolution")
    },
    async ({ intent, design_system_id, personality, count, layerId: toolLayerId }) => {
      const effectiveLayerId = toolLayerId ?? ctx.layerId;
      const dsId = design_system_id ?? ctx.designSystemId;
      ctx.debug("suggest_animation called", { intent, design_system_id: dsId, personality, count, layerId: effectiveLayerId });
      const intentLower = intent.toLowerCase();
      const matchedCategories = [];
      for (const [cat, keywords] of Object.entries(intentCategoryMap)) {
        const matchCount = keywords.filter((kw) => intentLower.includes(kw)).length;
        if (matchCount > 0) matchedCategories.push({ category: cat, score: matchCount / keywords.length });
      }
      matchedCategories.sort((a, b) => b.score - a.score);
      let allPrimitives = [...defaultAnimationPrimitives];
      let primitivesFromDb = false;
      if (ctx.supabase && dsId && effectiveLayerId) {
        try {
          const { data, error } = await ctx.supabase.rpc("get_resolved_animation_primitives", {
            p_design_system_id: dsId,
            p_layer_id: effectiveLayerId
          });
          if (!error && data && data.length > 0) {
            allPrimitives = data.map(mapAnimPrimitiveRow);
            primitivesFromDb = true;
          }
        } catch (err2) {
          ctx.debug("get_resolved_animation_primitives RPC failed, falling back to direct query", err2);
        }
      }
      if (!primitivesFromDb && ctx.supabase) {
        try {
          let query = ctx.supabase.from("animation_primitives").select("*");
          if (dsId) query = query.eq("design_system_id", dsId);
          const { data, error } = await query;
          if (!error && data && data.length > 0) allPrimitives = data.map(mapAnimPrimitiveRow);
        } catch (err2) {
          ctx.debug("Failed to fetch primitives for suggestion, using defaults", err2);
        }
      }
      let personalityData = null;
      let personalityApplied = false;
      if (personality) {
        personalityData = defaultMotionPersonalities.find((p4) => p4.slug === personality) || null;
        if (!personalityData && ctx.supabase) {
          try {
            if (dsId && effectiveLayerId) {
              const { data, error } = await ctx.supabase.rpc("get_resolved_motion_personalities", {
                p_design_system_id: dsId,
                p_layer_id: effectiveLayerId
              });
              if (!error && data) {
                const match = data.find((p4) => p4.slug === personality);
                if (match) personalityData = mapPersonalityRow(match);
              }
            }
            if (!personalityData && dsId) {
              const { data, error } = await ctx.supabase.from("motion_personalities").select("*").eq("slug", personality).eq("design_system_id", dsId).maybeSingle();
              if (!error && data) personalityData = mapPersonalityRow(data);
            }
          } catch (err2) {
            ctx.debug("Failed to fetch personality from database", err2);
          }
        }
        if (personalityData) personalityApplied = true;
      }
      const scored = allPrimitives.map((primitive) => {
        let score = 0;
        let rationale = "";
        const catMatch = matchedCategories.find((mc) => mc.category === primitive.category);
        if (catMatch) {
          score += catMatch.score * 0.6;
          rationale = `Category '${primitive.category}' matches intent keywords`;
        }
        if (intentLower.includes(primitive.slug) || intentLower.includes(primitive.name.toLowerCase())) {
          score += 0.4;
          rationale = `Direct name match for '${primitive.name}'`;
        }
        if (primitive.description.toLowerCase().split(" ").some((word) => intentLower.includes(word) && word.length > 3)) {
          score += 0.15;
          if (!rationale) rationale = "Description matches intent";
        }
        if (personalityData) {
          if (personalityData.defaultEntrance === primitive.slug && matchedCategories.some((mc) => mc.category === "entrance")) {
            score += 0.2;
            rationale += " (personality default entrance)";
          }
          if (personalityData.defaultExit === primitive.slug && matchedCategories.some((mc) => mc.category === "exit")) {
            score += 0.2;
            rationale += " (personality default exit)";
          }
        }
        const resolvedDuration = personalityData?.durationOverrides?.[primitive.defaultDuration] || animDurationTokenValues[primitive.defaultDuration] || "200ms";
        const resolvedEasing = personalityData?.easingOverrides?.[primitive.defaultEasing] || animEasingTokenValues[primitive.defaultEasing] || animEasingTokenValues["enter"];
        return {
          primitive: { name: primitive.name, slug: primitive.slug, category: primitive.category, cssClass: primitive.cssClass, composable: primitive.composable, description: primitive.description },
          confidence: Math.min(score, 1),
          rationale: rationale || "General match based on category proximity",
          timing: { duration: primitive.defaultDuration, durationValue: resolvedDuration, easing: primitive.defaultEasing, easingValue: resolvedEasing }
        };
      });
      scored.sort((a, b) => b.confidence - a.confidence);
      const topSuggestions = scored.slice(0, count);
      const suggestions = topSuggestions.filter((s) => s.confidence > 0).map((s) => ({
        ...s,
        alternatives: scored.filter((alt) => alt.primitive.slug !== s.primitive.slug && alt.confidence > 0).slice(0, 2).map((alt) => ({ name: alt.primitive.name, slug: alt.primitive.slug, confidence: alt.confidence }))
      }));
      if (suggestions.length === 0) {
        const fallback = allPrimitives.find((p4) => p4.slug === "fade-in") || allPrimitives[0];
        if (fallback) {
          suggestions.push({
            primitive: { name: fallback.name, slug: fallback.slug, category: fallback.category, cssClass: fallback.cssClass, composable: fallback.composable, description: fallback.description },
            confidence: 0.3,
            rationale: "Default fallback - fade-in is safe for most contexts",
            timing: { duration: fallback.defaultDuration, durationValue: animDurationTokenValues[fallback.defaultDuration] || "200ms", easing: fallback.defaultEasing, easingValue: animEasingTokenValues[fallback.defaultEasing] || animEasingTokenValues["enter"] },
            alternatives: []
          });
        }
      }
      const response = {
        suggestions,
        personality_applied: personalityApplied,
        personality: personalityData ? { name: personalityData.name, slug: personalityData.slug } : null,
        intent,
        matched_categories: matchedCategories.slice(0, 3)
      };
      return { content: [{ type: "text", text: JSON.stringify(response, null, 2) }] };
    }
  );
