function generateForbiddenSection(primitives) {
  if (primitives.length === 0) return "";
  const lines = [];
  lines.push("## Forbidden Elements & Patterns");
  lines.push("");
  lines.push("Do NOT generate these elements. Use the specified replacements instead.");
  lines.push("");
  const errors = primitives.filter((p4) => p4.severity === "error");
  const warnings = primitives.filter((p4) => p4.severity === "warning");
  if (errors.length > 0) {
    lines.push("### Errors (must not use)");
    lines.push("");
    lines.push("| Forbidden | Use Instead | Why |");
    lines.push("|-----------|-------------|-----|");
    for (const p4 of errors) {
      lines.push(`| \`${p4.element}\` | ${p4.replacement} | ${p4.reason} |`);
    }
    lines.push("");
  }
  if (warnings.length > 0) {
    lines.push("### Warnings (avoid)");
    lines.push("");
    lines.push("| Forbidden | Use Instead | Why |");
    lines.push("|-----------|-------------|-----|");
    for (const p4 of warnings) {
      lines.push(`| \`${p4.element}\` | ${p4.replacement} | ${p4.reason} |`);
    }
    lines.push("");
  }
  lines.push("---");
  lines.push("");
  return lines.join("\n");
}
function generateContextRulesSection(rules) {
  if (rules.length === 0) return "";
  const lines = [];
  lines.push("## File-Specific Rules");
  lines.push("");
  lines.push("These constraints apply when editing files matching the specified patterns.");
  lines.push("");
  for (const rule of rules) {
    lines.push(`### \`${rule.file_pattern}\``);
    if (rule.enforcement_level === "suggest") {
      lines.push("> **Advisory**: set to `suggest`. Surfaced for information;");
      lines.push("> not a requirement, and not a reason to change code.");
      lines.push("");
    }
    if (rule.description) {
      lines.push(rule.description);
    }
    lines.push("");
    if (Array.isArray(rule.constraints) && rule.constraints.length > 0) {
      for (const c2 of rule.constraints) {
        const cObj = c2;
        const type = cObj.type ?? (cObj.must_use ? "required" : "constraint");
        if (!constraintTypeIsHandled(type)) continue;
        const mustUse = cObj.mustUse ?? cObj.must_use ?? "";
        const reason = cObj.reason ?? "";
        if (mustUse) {
          lines.push(`- **${type}**: Use \`${mustUse}\`${reason ? ` \u2014 ${reason}` : ""}`);
        }
      }
      lines.push("");
    }
    const presets = rule.suggested_presets ?? [];
    if (presets.length > 0) {
      lines.push(`**Suggested presets:** ${presets.join(", ")}`);
      lines.push("");
    }
  }
  lines.push("---");
  lines.push("");
  return lines.join("\n");
}
function getContextUsageInstructions(format) {
  switch (format) {
    case "claude":
      return "Place CLAUDE.md in your project root. Claude Code and Claude Desktop will automatically read it.";
    case "cursor":
      return "Place .cursorrules in your project root. Cursor will automatically use it for context.";
    case "copilot":
      return "Place copilot-instructions.md in .github/ directory. GitHub Copilot will use it for context.";
  }
}
